1|/* Design tokens: two layers.
2| *
3| * Skin layer (this file's first block): fonts, sizes, measure, spacing,
4| * motion. Shared by every skin (`html[data-skin]`); a skin adds an
5| * `html[data-skin="x"]` block (plus an
6| * `html[data-skin="x"][data-theme="dark"]` block for dark-mode tweaks)
7| * overriding these same names. Components only read tokens, so switching
8| * skins never touches component code.
9| *
10| * Theme colour layer (the blocks below): light and dark palettes,
11| * selected by `data-theme`. Skins do not redefine colours here. */
12|
13|:root,
14|html[data-skin] {
15|  --font-ui: var(--font-instrument, "Instrument Sans"), -apple-system, blinkmacsystemfont,
16|    "Segoe UI", system-ui, sans-serif;
17|  --font-book: var(--font-newsreader, "Newsreader"), georgia, "Times New Roman", charter, serif;
18|
19|  --font-size-sm: 0.875rem;
20|  --font-size-base: 1rem;
21|  --font-size-lg: 1.25rem;
22|  --font-size-title: 1.75rem;
23|  --line-height-body: 1.7;
24|
25|  --measure-reading: 60ch;
26|
27|  --space-xs: 0.5rem;
28|  --space-sm: 0.75rem;
29|  --space-md: 1.25rem;
30|  --space-lg: 2rem;
31|
32|  --motion-duration: 150ms;
33|  --motion-expand: 260ms;
34|}
35|
36|:root,
37|html[data-theme="light"] {
38|  color-scheme: light;
39|
40|  --color-accent: #0866ff;
41|  --color-accent-hover: #0064e0;
42|  /* Fills keep white icons readable in both modes; text uses --color-accent. */
43|  --color-accent-fill: #0866ff;
44|  --color-on-accent: #ffffff;
45|  --color-text: #1c2b33;
46|  --color-text-muted: #5b6b76;
47|  --color-surface: #ffffff;
48|  --color-surface-soft: #f1f4f7;
49|  --color-border: #d9e0e7;
50|  --color-paper-dim: #e7e0cf;
51|  --color-select: #cfe1ff;
52|}
53|
54|html[data-theme="dark"] {
55|  color-scheme: dark;
56|
57|  --color-accent: #2d88ff;
58|  --color-accent-hover: #4a9bff;
59|  --color-accent-fill: #0866ff;
60|  --color-on-accent: #ffffff;
61|  --color-text: #e4e6eb;
62|  --color-text-muted: #9aa5b1;
63|  --color-surface: #0b1215;
64|  --color-surface-soft: #151c21;
65|  --color-border: #232d34;
66|  --color-paper-dim: #1a2128;
67|  --color-select: #1e3a5f;
68|}
69|
70|@media (prefers-reduced-motion: reduce) {
71|  :root {
72|    --motion-duration: 0ms;
73|    --motion-expand: 0ms;
74|  }
75|}
76|
77|/* Read-along narration. The word mark and sentence tint are tokens so
78| * skins switch them without touching components. The default skin (and
79| * any skin outside the three treatments) uses the engraving values in
80| * the theme blocks; watercolor/chihiro and ink/comic skins override them.
81| * Geometry (hairline rule, bleed radius, hand-drawn circle) lives in
82| * app/styles/narration.css and keys off the treatment attribute. */
83|:root,
84|html[data-theme="light"] {
85|  --narration-mark: #ffffff;
86|  --narration-mark-edge: rgba(28, 43, 51, 0.6);
87|  --narration-glow: rgba(28, 43, 51, 0.12);
88|  --narration-sentence: rgba(28, 43, 51, 0.055);
89|  --narration-rule: rgba(28, 43, 51, 0.6);
90|}
91|
92|html[data-theme="dark"] {
93|  --narration-mark: #0b1215;
94|  --narration-mark-edge: rgba(228, 230, 235, 0.6);
95|  --narration-glow: rgba(0, 0, 0, 0.4);
96|  --narration-sentence: rgba(228, 230, 235, 0.07);
97|  --narration-rule: rgba(228, 230, 235, 0.55);
98|}
99|
100|/* Watercolor: warm sienna bleed with a darker pooled edge. */
101|html[data-skin="watercolor"],
102|html[data-skin="chihiro"] {
103|  --narration-mark: rgba(214, 134, 96, 0.3);
104|  --narration-mark-edge: rgba(184, 98, 62, 0.35);
105|  --narration-glow: rgba(214, 134, 96, 0.25);
106|  --narration-sentence: rgba(101, 139, 168, 0.12);
107|  --narration-rule: rgba(184, 98, 62, 0.5);
108|}
109|
110|html[data-skin="watercolor"][data-theme="dark"],
111|html[data-skin="chihiro"][data-theme="dark"] {
112|  --narration-mark: rgba(214, 134, 96, 0.32);
113|  --narration-mark-edge: rgba(214, 134, 96, 0.5);
114|  --narration-glow: rgba(214, 134, 96, 0.28);
115|  --narration-sentence: rgba(101, 139, 168, 0.16);
116|  --narration-rule: rgba(214, 134, 96, 0.6);
117|}
118|
119|/* Ink doodle: the circle stroke is the mark; the tint stays faint. */
120|html[data-skin="ink"],
121|html[data-skin="comic"] {
122|  --narration-mark: rgba(43, 52, 66, 0.85);
123|  --narration-mark-edge: rgba(43, 52, 66, 0.5);
124|  --narration-glow: rgba(43, 52, 66, 0.12);
125|  --narration-sentence: rgba(28, 43, 51, 0.05);
126|  --narration-rule: rgba(43, 52, 66, 0.7);
127|}
128|
129|html[data-skin="ink"][data-theme="dark"],
130|html[data-skin="comic"][data-theme="dark"] {
131|  --narration-mark: rgba(228, 230, 235, 0.8);
132|  --narration-mark-edge: rgba(228, 230, 235, 0.45);
133|  --narration-glow: rgba(0, 0, 0, 0.4);
134|  --narration-sentence: rgba(228, 230, 235, 0.06);
135|  --narration-rule: rgba(228, 230, 235, 0.6);
136|}

