62|function defaultSplit(): number {
63|  if (typeof window === "undefined") return 320;
64|  return clampSplitWidth(Math.round(Math.min(1200, window.innerWidth - 80) * 0.3), window.innerWidth);
65|}
66|
67|export function Divider() {
68|  const [width, setWidth] = useState(defaultSplit);
69|  const [viewport, setViewport] = useState(1280);
70|  const ref = useRef<HTMLDivElement | null>(null);
71|
72|  useEffect(() => {
73|    const measure = () => setViewport(window.innerWidth);
74|    measure();
75|    window.addEventListener("resize", measure);
76|    try {
77|      const saved = Number(window.localStorage.getItem(SPLIT_KEY));
78|      if (Number.isFinite(saved) && saved > 0) {
79|        setWidth(clampSplitWidth(saved, window.innerWidth));
80|        return () => window.removeEventListener("resize", measure);
81|      }
82|    } catch {
83|      // Fresh default below.
84|    }
85|    setWidth(defaultSplit());
86|    return () => window.removeEventListener("resize", measure);
87|  }, []);
88|
89|  useEffect(() => {
90|    document.documentElement.style.setProperty("--pane-w", `${width}px`);
91|  }, [width]);
92|
93|  function commit(next: number) {
94|    const clamped = clampSplitWidth(next, window.innerWidth);
95|    setWidth(clamped);
96|    try {
97|      window.localStorage.setItem(SPLIT_KEY, String(clamped));
98|    } catch {
99|      // Dragging still works for the session.
100|    }
101|  }
102|
103|  return (
104|    <div
105|      ref={ref}
106|      className="pane-divider"
107|      role="separator"
108|      aria-orientation="vertical"
109|      aria-label="Resize image pane"
110|      aria-valuemin={SPLIT_MIN_PX}
111|      aria-valuemax={clampSplitWidth(Number.MAX_SAFE_INTEGER, viewport)}
112|      aria-valuenow={width}
113|      tabIndex={0}
114|      title="Drag to resize, double-click to reset"
115|      onDoubleClick={() => commit(defaultSplit())}
116|      onKeyDown={(e) => {
117|        if (e.key === "ArrowLeft") {
118|          e.preventDefault();
119|          commit(width - 16);
120|        } else if (e.key === "ArrowRight") {
121|          e.preventDefault();
122|          commit(width + 16);
123|        }
124|      }}
125|      onPointerDown={(e) => {
126|        (e.target as HTMLElement).setPointerCapture?.(e.pointerId);
127|        const move = (ev: PointerEvent) => {
128|          const grid = ref.current?.parentElement?.getBoundingClientRect();
129|          if (grid) commit(ev.clientX - grid.left);
130|        };
131|        const up = () => {
132|          window.removeEventListener("pointermove", move);
133|          window.removeEventListener("pointerup", up);
134|        };
135|        window.addEventListener("pointermove", move);
136|        window.addEventListener("pointerup", up);
137|      }}
138|    >
139|      <span className="grip" aria-hidden="true">
140|        |
141|      </span>
142|    </div>
143|  );
