{"content":"/* Ex-libris style stamp: the large home switcher and the small reader
 * switcher. Faces keep their skin paper in both themes (opaque objects
 * stay readable); the pill, focus ring and medal use theme tokens. */

.home-wrap {
  position: relative;
}

.style-stamp-home {
  position: absolute;
  top: 2px;
  right: 0;
  z-index: 60;
  width: 132px;
}

.style-stamp-wrap {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.style-stamp {
  position: relative;
  width: 104px;
  height: 104px;
  border-radius: 50%;
  cursor: pointer;
  padding: 0;
  background: none;
  border: 0;
  color: var(--color-text);
}

.style-stamp:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 4px;
  border-radius: 50%;
}

.style-stamp-face {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  transition:
    transform var(--motion-duration) ease,
    box-shadow var(--motion-duration) ease;
}

.style-stamp:hover .style-stamp-face {
  transform: translateY(-3px) rotate(4deg);
}

html[data-skin="engraving"] .style-stamp-face {
  background: #f7f1de;
  border: 2px solid #2a241c;
  box-shadow:
    inset 0 0 0 3px #f7f1de,
    inset 0 0 0 4px rgba(42, 36, 28, 0.6),
    0 3px 0 rgba(42, 36, 28, 0.35),
    0 8px 16px -8px rgba(42, 36, 28, 0.6);
}

html[data-skin="engraving"] .style-stamp:hover .style-stamp-face {
  box-shadow:
    inset 0 0 0 3px #f7f1de,
    inset 0 0 0 4px rgba(42, 36, 28, 0.6),
    0 5px 0 rgba(42, 36, 28, 0.3),
    0 14px 24px -8px rgba(42, 36, 28, 0.6);
}

html[data-skin="watercolor"] .style-stamp-face {
  background: radial-gradient(
    circle at 42% 38%,
    rgba(220, 233, 255, 0.98),
    rgba(141, 184, 255, 0.55) 72%,
    rgba(141, 184, 255, 0.3)
  );
  border: 2px solid rgba(91, 127, 184, 0.9);
  box-shadow: 0 8px 18px -10px rgba(31, 42, 68, 0.5);
}

html[data-skin="watercolor"] .style-stamp:hover .style-stamp-face {
  box-shadow: 0 14px 26px -10px rgba(31, 42, 68, 0.55);
}

html[data-skin="ink"] .style-stamp-face {
  background: #fff;
  border: 2.6px solid var(--color-accent-fill);
  box-shadow: 3px 4px 0 rgba(8, 102, 255, 0.16);
}

html[data-skin="ink"] .style-stamp:hover .style-stamp-face {
  box-shadow: 4px 8px 0 rgba(8, 102, 255, 0.2);
}

html[data-skin="pencil"] .style-stamp-face {
  background: #f6f6f4;
  border: 1.5px solid #9aa0a6;
  box-shadow:
    inset 0 0 0 3px #f6f6f4,
    inset 0 0 0 4px rgba(44, 47, 52, 0.45),
    0 6px 14px -8px rgba(44, 47, 52, 0.5);
}

html[data-skin="pencil"] .style-stamp:hover .style-stamp-face {
  box-shadow:
    inset 0 0 0 3px #f6f6f4,
    inset 0 0 0 4px rgba(44, 47, 52, 0.45),
    0 10px 20px -8px rgba(44, 47, 52, 0.5);
}

html[data-skin="comic"] .style-stamp-face {
  background: #fffdf4;
  border: 3px solid #14161c;
  box-shadow: 4px 4px 0 #14161c;
}

html[data-skin="comic"] .style-stamp:hover .style-stamp-face {
  box-shadow: 5px 6px 0 #14161c;
}

html[data-skin="chihiro"] .style-stamp-face {
  background: #fff7ec;
  border: 2px solid #c9a227;
  box-shadow:
    inset 0 0 0 3px #fff7ec,
    inset 0 0 0 4px rgba(201, 162, 39, 0.55),
    0 8px 18px -10px rgba(201, 162, 39, 0.7);
}

html[data-skin="chihiro"] .style-stamp:hover .style-stamp-face {
  box-shadow:
    inset 0 0 0 3px #fff7ec,
    inset 0 0 0 4px rgba(201, 162, 39, 0.55),
    0 12px 24px -10px rgba(201, 162, 39, 0.75);
}

.style-stamp-hit .style-stamp-face {
  animation: stamp-press 300ms ease;
}

html[data-skin="engraving"] .style-stamp-hit .style-stamp-face {
  animation: stamp-press-engrave 380ms ease;
}

html[data-skin="watercolor"] .style-stamp-hit .style-stamp-face {
  animation: stamp-press-watercolor 380ms ease;
}

@keyframes stamp-press {
  0% { transform: none; }
  40% { transform: translateY(4px) scale(0.94); }
  100% { transform: none; }
}

@keyframes stamp-press-engrave {
  0% { transform: none; }
  35% { transform: translateY(5px) scale(0.9); }
  70% { transform: translateY(-1px) scale(1.01); }
  100% { transform: none; }
}

@keyframes stamp-press-watercolor {
  0% { transform: none; }
  40% { transform: scale(1.05, 0.9); }
  70% { transform: scale(0.98, 1.02); }
  100% { transform: none; }
}

.style-stamp-ring {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.style-stamp-ringtxt {
  font-size: 12.5px;
  letter-spacing: 0.06em;
  font-family: var(--font-ui);
}

html[data-skin="engraving"] .style-stamp-ringtxt {
  font-family: var(--font-book);
  fill: #2a241c;
}

html[data-skin="watercolor"] .style-stamp-ringtxt {
  font-size: 14px;
  font-style: italic;
  fill: #1f2a44;
}

html[data-skin="ink"] .style-stamp-ringtxt {
  font-weight: 700;
  fill: var(--color-accent-fill);
}

html[data-skin="pencil"] .style-stamp-ringtxt {
  fill: #2c2f34;
}

html[data-skin="comic"] .style-stamp-ringtxt {
  font-weight: 700;
  fill: #14161c;
}

html[data-skin="chihiro"] .style-stamp-ringtxt {
  font-family: var(--font-book);
  font-style: italic;
  fill: #2a2a33;
}

.style-stamp-medal {
  position: absolute;
  inset: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent-fill);
}

.style-stamp-medal svg {
  width: 30px;
  height: 30px;
  display: block;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.style-stamp-inkring {
  position: absolute;
  inset: -2px;
  border-radius: 50%;
  pointer-events: none;
  opacity: 0;
  border: 3px solid var(--color-accent-fill);
}

.style-stamp-hit .style-stamp-inkring {
  animation: stamp-inkring 550ms ease;
}

@keyframes stamp-inkring {
  0% { opacity: 0.8; transform: scale(0.82); }
  100% { opacity: 0; transform: scale(1.22); }
}

/* Left of the stamp on desktop so it never covers the hero title. */
.style-stamp-now {
  position: absolute;
  right: calc(100% + 10px);
  top: 37px;
  margin: 0;
  font-family: var(--font-ui);
  font-size: 12.5px;
  color: var(--color-text-muted);
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  padding: 4px 10px;
  border-radius: 20px;
  box-shadow: 0 4px 14px rgba(20, 30, 60, 0.12);
  white-space: nowrap;
  opacity: 0;
  visibility: hidden;
  transform: translateX(4px);
  transition:
    opacity 160ms ease,
    transform 160ms ease,
    visibility 0s linear 260ms;
  pointer-events: none;
}

.style-stamp-now.style-stamp-show {
  opacity: 1;
  visibility: visible;
  transform: none;
  transition:
    opacity 160ms ease,
    transform 160ms ease,
    visibility 0s;
}

.style-stamp-now b {
  color: var(--color-accent);
}

/* Small reader switcher: theme-button sized, boxless, no ring text. */
.style-stamp-wrap-small {
  flex: none;
}

.style-stamp-wrap-small .style-stamp {
  width: 34px;
  height: 34px;
}

.style-stamp-wrap-small .style-stamp-medal {
  inset: 0;
}

.style-stamp-wrap-small .style-stamp-medal svg {
  width: 18px;
  height: 18px;
}

.style-stamp-wrap-small .style-stamp:hover .style-stamp-face {
  transform: translateY(-1px);
}

.style-stamp-wrap-small .style-stamp-inkring {
  border-width: 2px;
}

.style-stamp-wrap-small .style-stamp-now {
  right: 0;
  top: calc(100% + 6px);
  transform: translateY(-4px);
  z-index: 70;
}

.style-stamp-wrap-small .style-stamp-now.style-stamp-show {
  transform: none;
}

/* Narrow home: the stamp sits in flow above the hero, pill below it. */
@media (max-width: 699px) {
  .style-stamp-home {
    position: static;
    margin: 0 0 var(--space-md) auto;
  }

  .style-stamp-home .style-stamp-now {
    right: auto;
    left: 50%;
    top: calc(100% + 6px);
    transform: translate(-50%, -4px);
  }

  .style-stamp-home .style-stamp-now.style-stamp-show {
    transform: translate(-50%, 0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .style-stamp-face,
  .style-stamp:hover .style-stamp-face,
  .style-stamp-hit .style-stamp-face,
  .style-stamp-hit .style-stamp-inkring {
    animation: none !important;
    transition: opacity 200ms ease !important;
    transform: none !important;
  }

  .style-stamp-now,
  .style-stamp-now.style-stamp-show {
    transition: opacity 200ms ease !important;
    transform: none !important;
  }
}
